function render() { document.getElementById('bankBadge').textContent=state.bank.filter(row=>row.status!=='matched').length;document.getElementById('unallocatedBadge').textContent=state.advice.filter(row=>!row.invoice).length+state.bank.filter(row=>row.status==='unmatched').length;document.getElementById('breadcrumb').innerHTML=`<span>Workspace</span><b>/</b><strong>${navTitle(currentView)}</strong>`;document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===currentView)); const renderers={dashboard:renderDashboard,invoices:renderInvoices,customers:renderCustomers,advice:renderAdvice,bank:renderBank,returns:renderReturns,debit:renderDebit,unallocated:renderUnallocated,reports:renderReports,sync:renderSync,settings:renderSettings}; pageCounts=Object.create(null);const content=renderers[currentView]();app.innerHTML=content+pageControls(); bindPageEvents(); }
function bindPageEvents() {
  app.querySelectorAll('[data-page-key]').forEach(button=>button.onclick=()=>{pagePositions[button.dataset.pageKey]=Number(button.dataset.pageNumber);render();});
  app.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.view)));
  app.querySelectorAll('[data-invoice]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();openInvoice(b.dataset.invoice)}));
  app.querySelectorAll('[data-customer]').forEach(b=>b.addEventListener('click',()=>openCustomer(b.dataset.customer)));
  app.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();Promise.resolve(action(b.dataset.action,b.dataset)).catch(error=>showToast(error.message))}));
  if (sharedSession?.user.role === 'viewer') app.querySelectorAll('[data-action]').forEach(button=>{if(!['export','clear-filters','sync'].includes(button.dataset.action)){button.disabled=true;button.title='Viewer access';}});
  window.bindTeamControls?.();
  const search=document.getElementById('invoiceSearch');if(search)search.addEventListener('input',e=>{invoiceFilter.search=e.target.value;render();});
  const status=document.getElementById('statusFilter');if(status)status.addEventListener('change',e=>{invoiceFilter.status=e.target.value;render();});
}
function go(view) { currentView=view;document.getElementById('sidebar').classList.remove('open');render();window.scrollTo(0,0); }

function action(name,data) { if(name==='export') return exportReport(data.report); if(name==='sync') return runSync(); if(name==='import') return openImport();if(name==='connect-onedrive') return openConnect();if(name==='new-invoice')return openNewInvoice();if(name==='new-bank')return openBankReceipt();if(name==='customer-terms')return openCustomerTerms();if(name==='add-advice')return openAdvice();if(name==='new-debit')return openDebit();if(name==='map-bank'||name==='map-advice'||name==='map-debit')return openMap(name,data.ref);if(name==='match-selected')return matchEligible();if(name==='clear-filters'){invoiceFilter={search:'',status:'all'};return render();}if(name==='reset-data'){if(sharedSession)return showToast('Shared data can only be replaced through an administrator backup restore.');state=clone(seed);initializeCustomerTerms();persist();render();return showToast('Sample workspace restored.');}if(name==='view-errors')return showToast('Source-file import is not configured.'); }
function modal(title,subtitle,content,footer='') { const layer=document.getElementById('modalLayer');layer.innerHTML=`<div class="modal"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(subtitle||'')}</p></div><button class="modal-close" data-close-modal>×</button></div><div class="modal-content">${content}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div>`;layer.classList.remove('hidden');layer.querySelectorAll('[data-close-modal]').forEach(b=>b.onclick=closeModal);layer.onclick=e=>{if(e.target===layer)closeModal();};return layer; }
function closeModal(){document.getElementById('modalLayer').classList.add('hidden');}
function openInvoice(id) { const x=allInvoices().find(i=>i.id===id);if(!x)return;const ret=state.returns.filter(r=>r.invoice===id),pr=state.priceReturns.filter(r=>r.invoice===id),adv=state.advice.filter(a=>a.invoice===id),bank=state.bank.filter(b=>adv.some(a=>a.utr===b.ref));const deducted=[['Qty return',x.qtyReturn],['Price return',x.priceReturn],['Payment',x.Payment],['TDS',x.TDS],['PPV',x.PPV],['PQV',x.PQV],['CCOGS',x.CCOGS],['TaxD',x.TaxD],['Round off',x.roundOff]];modal(`Invoice ${x.id}`,`${x.customer} · ${x.code}`,`<div class="detail-top"><div><small>Invoice date</small><b>${dateText(x.date)}</b></div><div><small>Invoice value</small><b>${fMoney(x.amount)}</b></div><div><small>Total adjusted</small><b>${fMoney(x.deducted+x.roundOff)}</b></div><div><small>Pending amount</small><b class="detail-highlight">${fMoney(x.pending)}</b></div></div><div class="detail-grid"><section class="detail-section"><h3>Reconciliation allocation</h3>${deducted.map(([n,v])=>`<div class="allocation-row"><span>${n}</span><b class="amount">${fMoney(v)}</b></div>`).join('')}<div class="allocation-row" style="margin-top:4px"><b>Final pending</b><b class="amount ${x.pending?'detail-highlight':''}">${fMoney(x.pending)}</b></div></section><section class="detail-section"><h3>Original invoice</h3><div class="allocation-row"><span>Quantity</span><b>${x.qty}</b></div><div class="allocation-row"><span>Rate</span><b>${fMoney(x.rate)}</b></div><div class="allocation-row"><span>Credit terms</span><b>${x.creditDays} days</b></div><div class="allocation-row"><span>Due date</span><b>${dateText(x.dueDate)}</b></div><div class="allocation-row"><span>Age</span><b>${x.age} days</b></div><div class="allocation-row"><span>Reconciliation status</span>${statusMarkup(x.status)}</div></section></div><section class="detail-section" style="margin-top:15px"><h3>Transaction history</h3><table class="data-table" style="min-width:0"><thead><tr><th>Date</th><th>Reference</th><th>Transaction</th><th class="right">Amount</th></tr></thead><tbody>${[...ret.map(r=>({date:r.date,ref:r.id,type:'Quantity return',amount:r.amount})),...pr.map(r=>({date:r.date,ref:r.id,type:'Price return',amount:r.amount})),...adv.map(a=>({date:a.date,ref:a.id+' · '+a.utr,type:a.type,amount:a.amount})),...bank.map(b=>({date:b.date,ref:b.ref,type:'Verified bank receipt',amount:b.amount}))].sort((a,b)=>a.date.localeCompare(b.date)).map(r=>`<tr><td>${dateText(r.date)}</td><td>${esc(r.ref)}</td><td>${esc(r.type)}</td><td class="right strong">${fMoney(r.amount)}</td></tr>`).join('')||'<tr><td colspan="4" style="text-align:center;color:#8d97a8">No adjustments recorded</td></tr>'}</tbody></table></section>`,`<button class="btn" data-close-modal>Close</button><button class="btn" id="editRoundOff">Edit round off</button><button class="btn primary" data-modal-export="${esc(x.id)}">⇩ Export reconciliation</button>`);document.getElementById('editRoundOff').disabled=sharedSession?.user.role==='viewer';document.getElementById('editRoundOff').onclick=()=>openRoundOff(id);document.querySelector('[data-modal-export]')?.addEventListener('click',()=>exportReport('Invoice Outstanding',[x])); }
function openCustomer(customer) { const rows=allInvoices().filter(x=>x.customer===customer);const c=customerRows().find(x=>x.customer===customer);modal(customer,`${c.code} · ${c.count} invoice${c.count>1?'s':''}`,`<div class="detail-top"><div><small>Invoice value</small><b>${fMoney(c.invoice)}</b></div><div><small>Returns</small><b>${fMoney(c.returns)}</b></div><div><small>Payment received</small><b>${fMoney(c.payment)}</b></div><div><small>Pending amount</small><b class="detail-highlight">${fMoney(c.pending)}</b></div></div><div class="balance-split"><div><small>Overdue</small><b class="amount-red">${fMoney(c.overdue)}</b></div><div><small>Due</small><b>${fMoney(c.due)}</b></div></div><div style="margin-top:16px">${invoiceTable(rows)}</div>`,`<button class="btn" data-close-modal>Close</button><button class="btn primary" data-modal-export="customer">⇩ Export customer ledger</button>`);document.querySelector('[data-modal-export]')?.addEventListener('click',()=>exportReport('Customer Outstanding',rows)); }
function openImport() {return openConnect();}

async function openConnect(){
  if(sharedSession?.user.role !== 'admin') return showToast('Ask your administrator to connect OneDrive.');
  const status=await window.workspaceAPI('/api/onedrive/status');
  const missing=[...status.missing,...status.invalid];
  const content=status.ready
    ? `<p>${status.connected ? `Connected as <strong>${esc(status.account)}</strong>.` : 'Sign in with the Microsoft 365 account that owns your source files.'}</p><p>The connection can read files. Browsing does not change your financial records.</p>${status.connected?'<button class="btn primary" id="onedriveBrowse">Browse files</button> ':''}<button class="btn" id="onedriveAuthorize">${status.connected?'Reconnect':'Connect Microsoft 365'}</button>${status.connected?' <button class="btn" id="onedriveDisconnect">Disconnect</button>':''}`
    : `<p>Complete the Microsoft 365 registration, then add these Production environment variables in Netlify with the Functions scope:</p><ul>${[...new Set(missing)].map(key=>`<li><code>${esc(key)}</code>${status.invalid.includes(key)?' — check the format':''}</li>`).join('')}</ul><p>Use a <strong>Web</strong> redirect URI:</p><p><code>https://reconcileiq-urbanretail.netlify.app/api/onedrive/callback</code></p><p>Microsoft Graph delegated permission: <strong>Files.Read</strong>. Set the client secret and token key as secrets, then redeploy.</p><p><a href="https://entra.microsoft.com/" target="_blank" rel="noopener noreferrer">Open Microsoft Entra</a> · <a href="https://app.netlify.com/projects/reconcileiq-urbanretail/configuration/env" target="_blank" rel="noopener noreferrer">Open Netlify variables</a></p>`;
  const recovery=status.credentialError?'<p>The saved credentials cannot be opened with the current token key. Restore the original key, or reconnect to replace the saved connection.</p><button class="btn" id="onedriveDisconnect">Clear saved connection</button>':'';
  const layer=modal('Microsoft OneDrive',status.connected?'Connected':status.ready?'Ready to connect':'Setup required',content+recovery+(status.connected?' <button class="btn" id="onedriveJobs">Bulk imports</button>':''),'<button class="btn" data-close-modal>Close</button>');
  const jobs=layer.querySelector('#onedriveJobs');if(jobs)jobs.onclick=()=>openBulkImports().catch(error=>showToast(error.message));
  const connect=layer.querySelector('#onedriveAuthorize');
  if(connect) connect.onclick=async()=>{connect.disabled=true;try{const result=await window.workspaceAPI('/api/onedrive/connect','POST',{});window.location.assign(result.url);}catch(error){connect.disabled=false;showToast(error.message);}};
  const disconnect=layer.querySelector('#onedriveDisconnect');
  if(disconnect) disconnect.onclick=async()=>{disconnect.disabled=true;try{await window.workspaceAPI('/api/onedrive/disconnect','POST',{});await openConnect();showToast('OneDrive disconnected.');}catch(error){disconnect.disabled=false;showToast(error.message);}};
  const browse=layer.querySelector('#onedriveBrowse');if(browse) browse.onclick=()=>openOneDriveFolder().catch(error=>showToast(error.message));
}
async function openOneDriveFolder(folder='root',trail=[],page=''){
  const result=await window.workspaceAPI(`/api/onedrive/files?folder=${encodeURIComponent(folder)}&page=${encodeURIComponent(page)}`);
  const layer=modal('OneDrive files',trail.map(item=>item.name).join(' / ') || 'My files',`<p>Choose Import for an Excel (.xlsx) or CSV file, map the columns, then review the preview before saving. Files up to 100 MB use background preparation. Up to 200,000 records per register; the preview checks workspace capacity.</p><div class="table-wrap"><table><thead><tr><th>Name</th><th>Last modified</th><th>Action</th></tr></thead><tbody>${result.items.map((item,index)=>`<tr><td>${item.folder?'📁 ':''}${esc(item.name)}</td><td>${esc((item.modified || '').slice(0,10))}</td><td>${item.folder?`<button class="btn small" data-folder-index="${index}">Open folder</button>`:`${/\.(xlsx|csv)$/i.test(item.name)?`<button class="btn small primary" data-import-index="${index}">Import</button> `:''}${item.webUrl?`<a class="btn small" href="${esc(item.webUrl)}" target="_blank" rel="noopener noreferrer">Open file</a>`:''}`}</td></tr>`).join('') || '<tr><td colspan="3">This folder is empty.</td></tr>'}</tbody></table></div>`,`<button class="btn" id="onedriveBack">${page?'First page':trail.length?'Back':'Connection settings'}</button>${result.nextPage?'<button class="btn" id="onedriveNext">Next page</button>':''}<button class="btn" data-close-modal>Close</button>`);
  const navigate=task=>Promise.resolve(task).catch(error=>showToast(error.message));
  layer.querySelectorAll('[data-folder-index]').forEach(button=>button.onclick=()=>{const item=result.items[Number(button.dataset.folderIndex)];navigate(openOneDriveFolder(item.id,[...trail,{id:folder,name:item.name}]));});
  layer.querySelectorAll('[data-import-index]').forEach(button=>button.onclick=async()=>{button.disabled=true;button.textContent='Reading…';try{await openOneDriveImport(result.items[Number(button.dataset.importIndex)].id);}catch(error){button.disabled=false;button.textContent='Import';showToast(error.message);}});
  layer.querySelector('#onedriveBack').onclick=()=>navigate(page?openOneDriveFolder(folder,trail):trail.length?openOneDriveFolder(trail.at(-1).id,trail.slice(0,-1)):openConnect());
  const next=layer.querySelector('#onedriveNext');if(next) next.onclick=()=>navigate(openOneDriveFolder(folder,trail,result.nextPage));
}

async function openOneDriveImport(id){
  const [workbook,{definitions}]=await Promise.all([window.workspaceAPI('/api/onedrive/workbook?id='+encodeURIComponent(id)),window.workspaceAPI('/api/import/definitions')]);
  if(workbook.large){const job=await window.workspaceAPI('/api/import-jobs','POST',{fileId:id});return watchBulkImport(job.id);}
  return openImportMapping(workbook,definitions);
}
async function openBulkImports(){
  const {jobs}=await window.workspaceAPI('/api/import-jobs');
  const layer=modal('Bulk imports','Prepared data is available for six hours. Financial records change only after you confirm the preview.',`<div class="table-wrap"><table class="data-table"><thead><tr><th>File</th><th>Status</th><th>Action</th></tr></thead><tbody>${jobs.map(job=>`<tr><td>${esc(job.info.name)}</td><td>${esc(job.status)}${job.error?`<p>${esc(job.error)}</p>`:''}</td><td>${['queued','processing','ready'].includes(job.status)?`<button class="btn" data-bulk-job="${job.id}">${job.status==='ready'?'Map columns':'View progress'}</button>`:'—'}</td></tr>`).join('') || '<tr><td colspan="3">No recent bulk imports.</td></tr>'}</tbody></table></div>`,'<button class="btn" data-close-modal>Close</button>');
  layer.querySelectorAll('[data-bulk-job]').forEach(button=>button.onclick=()=>watchBulkImport(button.dataset.bulkJob).catch(error=>showToast(error.message)));
}
async function watchBulkImport(id){
  const layer=modal('Preparing bulk import','The workbook is read in the background. You can close this dialog and resume under Microsoft OneDrive → Bulk imports.',`<p id="bulkJobMarker" data-job="${esc(id)}">Checking progress…</p>`,'<button class="btn" data-close-modal>Close</button><button class="btn" id="cancelBulkImport">Cancel preparation</button>');
  layer.querySelector('#cancelBulkImport').onclick=async()=>{try{await window.workspaceAPI('/api/import-jobs/'+id,'DELETE',{});await openBulkImports();}catch(error){showToast(error.message);}};
  const active=()=>!layer.classList.contains('hidden') && layer.querySelector('#bulkJobMarker')?.dataset.job===id;
  while(active()){
    const job=await window.workspaceAPI('/api/import-jobs/'+id);if(!active())return;
    if(job.status==='ready'){
      const {definitions}=await window.workspaceAPI('/api/import/definitions');if(!active())return;
      return openImportMapping({jobId:id,name:job.info.name,sheets:job.info.sheets},definitions);
    }
    layer.querySelector('#bulkJobMarker').textContent=job.error || job.info.progress || job.status;
    if(!['queued','processing'].includes(job.status)){layer.querySelector('#cancelBulkImport').disabled=true;return;}
    await new Promise(resolve=>setTimeout(resolve,2000));
  }
}
function suggestImportColumns(fields,headers,type){
  const normalize=value=>String(value).toLowerCase().replace(/[^a-z0-9]/g,'');
  const aliases={id:type==='invoices'?['invoiceno','invoicenumber','invoiceid','billno']:['recordnumber','id','referenceno','documentno','adviceno','debitnoteno','returnno'],customer:['customer','customername','partyname','buyername'],date:['date','invoicedate','billdate','receiptdate','transactiondate'],amount:['amount','invoiceamount','netamount','creditamount','totalamount'],code:['customercode','code','partycode'],roundOff:['roundoff','rounding'],creditDays:['creditdays','creditperiod','paymenttermsdays'],ref:['utr','bankreference','reference','bankref','transactionreference'],invoice:['invoiceno','invoicenumber','invoiceid','invoice'],type:['type','advicetype','deductiontype'],utr:['utr','bankreference','paymentreference'],description:['description','remarks','narration']};
  const used=new Set(),result={};for(const f of fields){const names=[normalize(f.label),normalize(f.key),...(aliases[f.key] || [])];const index=headers.findIndex((h,i)=>!used.has(i) && names.includes(normalize(h)));if(index>=0){result[f.key]=index;used.add(index);}}return result;
}
function openImportMapping(workbook,definitions,sheetIndex=0,type='invoices',headerRow=1,chosen=null,dateFormat='dmy'){
  const sheet=workbook.sheets[sheetIndex];const headers=sheet.rows[headerRow-1] || [];
  const width=Math.max(sheet.columnCount || 0,0,...sheet.rows.map(row=>row.length));const labels=Array.from({length:width},(_,i)=>`${i+1}: ${headers[i] || '(blank header)'}`);
  const fields=definitions[type].fields;const mapping=chosen || suggestImportColumns(fields,headers,type);
  const layer=modal('Map import columns',workbook.name,`<div class="mapping-grid"><label>Worksheet<select id="importSheet">${workbook.sheets.map((s,i)=>`<option value="${i}" ${i===sheetIndex?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Data type<select id="importType">${Object.entries(definitions).map(([key,d])=>`<option value="${key}" ${key===type?'selected':''}>${esc(d.label)}</option>`).join('')}</select></label><label>Header row<input id="importHeader" type="number" min="1" max="${sheet.maxRow || sheet.rows.length}" value="${headerRow}" /></label><label>Text date format<select id="importDateFormat"><option value="dmy" ${dateFormat==='dmy'?'selected':''}>DD/MM/YYYY</option><option value="mdy" ${dateFormat==='mdy'?'selected':''}>MM/DD/YYYY</option><option value="iso" ${dateFormat==='iso'?'selected':''}>YYYY-MM-DD</option><option value="excel" ${dateFormat==='excel'?'selected':''}>Excel serial numbers</option></select></label></div><p>Check the suggested columns. * Required. Excel date cells and YYYY-MM-DD dates are recognized automatically. For prepared workbooks, the table below is a sample of the first 50 rows.</p><div class="mapping-grid">${fields.map(f=>`<label>${esc(f.label)}${f.required?' *':''}<select data-import-field="${f.key}"><option value="">${f.required?'Choose column':'Not mapped'}</option>${labels.map((label,i)=>`<option value="${i}" ${mapping[f.key]===i?'selected':''}>${esc(label)}</option>`).join('')}</select></label>`).join('')}</div><p>${type==='invoices'?'Credit days are managed per customer. Material description is not imported.':type==='customerTerms'?'Existing customer credit days will be updated after confirmation.':'Import invoices first if these rows refer to invoice numbers.'}</p><p>Identical records are skipped. Conflicting identifiers block the import. Unrelated records stay in the workspace.</p><div class="table-wrap" style="max-height:180px"><table><thead><tr>${labels.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${sheet.rows.slice(headerRow,headerRow+3).map(row=>`<tr>${labels.map((_,i)=>`<td>${esc(row[i] ?? '')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="previewImport">Preview import</button>`);
  const reload=()=>{const nextHeader=Number(layer.querySelector('#importHeader').value);if(!Number.isInteger(nextHeader)||nextHeader<1||nextHeader>(sheet.maxRow || sheet.rows.length))return showToast('Choose a valid header row.');openImportMapping(workbook,definitions,Number(layer.querySelector('#importSheet').value),layer.querySelector('#importType').value,nextHeader,null,layer.querySelector('#importDateFormat').value);};
  layer.querySelector('#importSheet').onchange=()=>openImportMapping(workbook,definitions,Number(layer.querySelector('#importSheet').value),layer.querySelector('#importType').value,1,null,layer.querySelector('#importDateFormat').value);
  layer.querySelector('#importType').onchange=reload;layer.querySelector('#importHeader').onchange=reload;
  layer.querySelector('#previewImport').onclick=async()=>{
    const button=layer.querySelector('#previewImport');button.disabled=true;
    const selected={};layer.querySelectorAll('[data-import-field]').forEach(select=>{if(select.value!=='')selected[select.dataset.importField]=Number(select.value);});
    const format=layer.querySelector('#importDateFormat').value;
    const back=()=>openImportMapping(workbook,definitions,sheetIndex,type,headerRow,selected,format);
    try{await showImportPreview({type,...(workbook.jobId?{jobId:workbook.jobId,sheetKey:sheet.key}:{rows:sheet.rows.slice(headerRow)}),mapping:selected,startRow:headerRow+1,dateFormat:format},back);}catch(error){button.disabled=false;showToast(error.message);}
  };
}
async function showImportPreview(input,back){
  const preview=await window.workspaceAPI('/api/import/preview','POST',input);const counts=preview.counts;
  const layer=modal('Review import','Nothing is saved until you confirm.',`<p><strong>${counts.added}</strong> new · <strong>${counts.updated}</strong> credit-day updates · <strong>${counts.skipped}</strong> duplicates skipped · <strong>${counts.invalid}</strong> invalid · ${counts.blank} blank rows ignored</p>${preview.errors.length?`<p>Fix these issues in the file or column mapping, then preview again. No rows will be imported while errors remain.</p><ul>${preview.errors.map(e=>`<li>${e.row?`Row ${e.row}: `:''}${esc(e.message)}</li>`).join('')}</ul>`:''}<div class="table-wrap" style="max-height:330px"><table><thead><tr><th>Source row</th><th>Action</th><th>Mapped record (first 12)</th></tr></thead><tbody>${preview.sample.map(row=>`<tr><td>${row.sourceRow}</td><td>${esc(row.outcome)}</td><td>${esc(Object.entries(row.record).map(([k,v])=>`${k}: ${v}`).join(' · '))}</td></tr>`).join('')}</tbody></table></div>${!preview.canImport&&!counts.invalid?'<p>All records already exist, or this selection contains no new data.</p>':''}`,`<button class="btn" id="importBack">Back to mapping</button><button class="btn primary" id="confirmImport" ${preview.canImport?'':'disabled'}>Confirm import</button>`);
  layer.querySelector('#importBack').onclick=back;
  layer.querySelector('#confirmImport').onclick=async()=>{
    if(saving)return;const button=layer.querySelector('#confirmImport');button.disabled=true;saving=true;
    try{
      const result=await window.workspaceAPI('/api/import','POST',{...input,revision:preview.revision});
      state=result.state;workspaceRevision=result.revision;savedState=clone(state);sharedSession.state=clone(state);sharedSession.revision=workspaceRevision;
      closeModal();render();showToast(`${counts.added} records imported${counts.updated?`; ${counts.updated} credit-day mappings updated`:''}.`);
    }catch(error){showToast(error.message);if(error.status===409)await showImportPreview(input,back);else button.disabled=false;}
    finally{saving=false;}
  };
}

function openCustomerTerms() {
  modal('Customer credit days', 'Changes apply to every existing and future invoice for the customer.',
    `<div class="mapping-grid">${state.customerTerms.map((term,index)=>`<label>${esc(term.customer)}<input data-term-index="${index}" data-term-customer="${esc(term.customer)}" type="number" min="0" step="1" value="${term.creditDays}" /></label>`).join('')}</div>`,
    `<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveCustomerTerms">Save credit days</button>`);
  document.getElementById('saveCustomerTerms').onclick=async ()=>{try{
    const inputs=[...document.querySelectorAll('[data-term-index]')];
    if(inputs.some(input=>input.value.trim()===''||!Number.isInteger(Number(input.value))||Number(input.value)<0||Number(input.value)>3650)){
      showToast('Enter whole credit days from 0 to 3650 for each customer.');return;
    }
    inputs.forEach(input=>{const term=state.customerTerms.find(t=>customerKey(t.customer)===customerKey(input.dataset.termCustomer || state.customerTerms[Number(input.dataset.termIndex)].customer));if(term)term.creditDays=Number(input.value);});
    await persist();closeModal();render();showToast('Customer credit days saved. All invoice due dates recalculated.');
  }catch(error){showToast(error.message);}};
}

function openNewInvoice(){modal('Add invoice','Create a sales invoice record. Credit days are applied automatically from the customer mapping (45 days for a new customer).',`<div class="mapping-grid"><label>Invoice number<input id="newInvId" placeholder="INV-2026-00XXX" /></label><label>Customer name<input id="newInvCustomer" list="invoiceCustomers" placeholder="Customer name" /><datalist id="invoiceCustomers">${state.customerTerms.map(t=>`<option value="${esc(t.customer)}"></option>`).join('')}</datalist></label><label>Customer code<input id="newInvCode" placeholder="CUS-001" /></label><label>Invoice date<input id="newInvDate" type="date" value="${today}" /></label><label>Invoice amount<input id="newInvAmount" type="number" placeholder="0" /></label><label>Round off<input id="newInvRoundOff" type="number" step="0.01" value="0" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveInvoice">Save invoice</button>`);document.getElementById('saveInvoice').onclick=async ()=>{try{const id=document.getElementById('newInvId').value.trim(),customer=document.getElementById('newInvCustomer').value.trim(),amount=+document.getElementById('newInvAmount').value,roundOff=+document.getElementById('newInvRoundOff').value;if(!id||!customer||!amount){showToast('Invoice number, customer and amount are required.');return;}if(state.invoices.some(x=>x.id===id)){showToast('That invoice number already exists.');return;}state.invoices.unshift({id,customer,code:document.getElementById('newInvCode').value||'—',date:document.getElementById('newInvDate').value,amount,roundOff,qty:0,rate:0});initializeCustomerTerms();await persist();closeModal();render();showToast('Invoice saved and added to reconciliation.');}catch(error){showToast(error.message);}}; }
function openRoundOff(id){const invoice=state.invoices.find(x=>x.id===id);if(!invoice)return;const calculated=invoiceData(invoice);modal(`Round off · ${id}`,'Set a signed adjustment to clear a small balance. Positive values reduce pending. Credit days are managed by customer in Customer Summary.',`<div class="detail-top"><div><small>Current pending</small><b>${fMoney(calculated.pending)}</b></div><div><small>Current round off</small><b>${fMoney(calculated.roundOff)}</b></div><div><small>Credit days</small><b>${calculated.creditDays} days</b></div><div><small>Due date</small><b>${dateText(calculated.dueDate)}</b></div></div><div class="mapping-grid" style="margin-top:16px"><label>Round off amount<input id="roundOffAmount" type="number" step="0.01" value="${calculated.roundOff}" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveRoundOff">Save round off</button>`);document.getElementById('saveRoundOff').onclick=async ()=>{try{const roundOff=Number(document.getElementById('roundOffAmount').value);if(!Number.isFinite(roundOff)){showToast('Enter a valid round-off value.');return;}const target=state.invoices.find(x=>x.id===id);if(!target)throw new Error('This invoice no longer exists. Close this form and refresh.');target.roundOff=roundOff;await persist();closeModal();render();showToast('Round off saved; pending status recalculated.');}catch(error){showToast(error.message);}};}
function openAdvice(){const opts=state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.customer)}</option>`).join('');const bankRefs=state.bank.filter((x,i,a)=>x.status==='unmatched'&&a.findIndex(y=>y.ref===x.ref)===i);const utrOptions=bankRefs.map(x=>`<option value="${esc(x.ref)}">${esc(x.ref)} · ${dateText(x.date)} · ${fMoney(x.amount)}</option>`).join('');modal('Add payment advice entry','Select a mandatory bank reference from the unmapped bank receipts; transaction classification is restricted to six approved values.',`<div class="mapping-grid"><label>Customer<input id="advCustomer" placeholder="Customer name" /></label><label>Advice number<input id="advId" placeholder="PA-260XXX" /></label><label>Advice date<input id="advDate" type="date" value="${today}" /></label><label>Invoice <select id="advInvoice"><option value="">— Unallocated —</option>${opts}</select></label><label>Transaction type<select id="advType"><option>Payment</option><option>TDS</option><option>PPV</option><option>PQV</option><option>CCOGS</option><option>TaxD</option></select></label><label>Amount<input id="advAmount" type="number" placeholder="0" /></label><label>Transaction description<input id="advDescription" placeholder="Enter any description" /></label><label>Bank reference / UTR *<select id="advUtr"><option value="">Select an unmapped bank receipt</option>${utrOptions}</select></label></div>${bankRefs.length?'':'<div style="margin-top:12px;background:#fff5df;border-radius:7px;padding:10px;font-size:10px;color:#8d6d24">No unmapped bank receipts are available. Import or map a bank statement receipt first.</div>'}`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveAdvice">Save allocation</button>`);document.getElementById('advInvoice').onchange=e=>{if(e.target.value){const x=state.invoices.find(a=>a.id===e.target.value);document.getElementById('advCustomer').value=x.customer;}};document.getElementById('saveAdvice').onclick=async ()=>{try{const amount=+document.getElementById('advAmount').value,id=document.getElementById('advId').value.trim(),customer=document.getElementById('advCustomer').value.trim(),utr=document.getElementById('advUtr').value;if(!amount||!id||!customer||!utr){showToast('Advice number, customer, amount and bank reference / UTR are required.');return;}if(!bankRefs.some(x=>x.ref===utr)){showToast('Select a bank reference from the unmapped bank receipts.');return;}state.advice.unshift({id,customer,date:document.getElementById('advDate').value,invoice:document.getElementById('advInvoice').value,type:document.getElementById('advType').value,description:document.getElementById('advDescription').value.trim(),amount,utr});await persist();closeModal();render();showToast('Payment advice allocation saved.');}catch(error){showToast(error.message);}}; }
function openDebit(){modal('Add debit note','Debit notes are retained for audit and are not deducted automatically.',`<div class="mapping-grid"><label>Debit note number<input id="dnId" placeholder="DN-XXXX" /></label><label>Customer name<input id="dnCustomer" placeholder="Customer name" /></label><label>Date<input id="dnDate" type="date" value="${today}" /></label><label>Original invoice<select id="dnInvoice"><option value="">— No invoice reference —</option>${state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)}</option>`).join('')}</select></label><label>Amount<input id="dnAmount" type="number" placeholder="0" /></label><label>Debit note type<select id="dnType"><option>PPV</option><option>PQV</option><option>CCOGS</option><option>TAXD</option><option selected>Unknown</option></select></label></div><p style="font-size:9px;color:#8a95a8">The record will be marked Unmapped until its treatment is represented in payment advice or approved for adjustment.</p>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveDebit">Save debit note</button>`);document.getElementById('saveDebit').onclick=async ()=>{try{const id=document.getElementById('dnId').value.trim(),customer=document.getElementById('dnCustomer').value.trim(),amount=+document.getElementById('dnAmount').value;if(!id||!customer||!amount){showToast('Debit note number, customer and amount are required.');return;}state.debitNotes.unshift({id,customer,date:document.getElementById('dnDate').value,invoice:document.getElementById('dnInvoice').value,amount,type:document.getElementById('dnType').value,status:'Unmapped'});await persist();closeModal();render();showToast('Debit note added for review.');}catch(error){showToast(error.message);}}; }
function openMap(kind,ref){ const candidate=kind==='map-bank'?state.bank.find(x=>x.ref===ref):kind==='map-advice'?state.advice.find(x=>x.id===ref):state.debitNotes.find(x=>x.id===ref);if(!candidate)return;const source=kind==='map-bank'?'bank receipt':kind==='map-advice'?'payment advice':'debit note';modal(`Map ${source}`,'Choose the customer and invoice to resolve this transaction.',`<div class="detail-top"><div><small>Reference</small><b>${esc(candidate.ref||candidate.id)}</b></div><div><small>Date</small><b>${dateText(candidate.date)}</b></div><div><small>Amount</small><b>${fMoney(candidate.amount)}</b></div><div><small>Current customer</small><b>${esc(candidate.customer||'Unknown')}</b></div></div><div class="mapping-grid" style="margin-top:16px"><label>Customer<select id="mapCustomer"><option value="">Select customer</option>${[...new Set(state.invoices.map(x=>x.customer))].map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('')}</select></label><label>Invoice<select id="mapInvoice"><option value="">Select invoice</option>${state.invoices.map(x=>`<option value="${esc(x.id)}">${esc(x.id)} — ${esc(x.customer)}</option>`).join('')}</select></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveMap">Confirm mapping</button>`);document.getElementById('mapInvoice').onchange=e=>{if(e.target.value){const i=state.invoices.find(x=>x.id===e.target.value);document.getElementById('mapCustomer').value=i.customer;}};document.getElementById('saveMap').onclick=async ()=>{try{const invoice=document.getElementById('mapInvoice').value,customer=document.getElementById('mapCustomer').value;if(!invoice||!customer){showToast('Select both customer and invoice to complete mapping.');return;}const target=kind==='map-bank'?state.bank.find(x=>x.ref===ref):kind==='map-advice'?state.advice.find(x=>x.id===ref):state.debitNotes.find(x=>x.id===ref);if(!target)throw new Error('This transaction no longer exists. Refresh and try again.');if(kind==='map-bank'){target.customer=customer;target.status='review';target.advice='Manual mapping';}else if(kind==='map-advice'){target.invoice=invoice;target.customer=customer;}else{target.invoice=invoice;target.customer=customer;target.status='Included in adjustment';}await persist();closeModal();render();showToast(`${source[0].toUpperCase()+source.slice(1)} mapped successfully.`);}catch(error){showToast(error.message);}}; }
async function matchEligible(){try{
  let changed=0;
  state.bank.filter(row=>row.status!=='matched').forEach(receipt=>{
    if(state.bank.filter(row=>row.ref===receipt.ref).length!==1)return;
    const payments=state.advice.filter(advice=>advice.utr===receipt.ref&&advice.type==='Payment');
    if(payments.length&&Math.abs(sum(payments,row=>row.amount)-receipt.amount)<0.005){
      receipt.status='matched';receipt.advice=[...new Set(payments.map(row=>row.id))].join(', ');
      receipt.customer=[...new Set(payments.map(row=>row.customer))].join(', ');changed++;
    }
  });
  if(changed){await persist();render();}
  showToast(changed?`${changed} receipts matched successfully.`:'No exact amount/UTR matches were eligible. Duplicate references require review.');
}catch(error){showToast(error.message);}}

async function runSync(){try{await window.refreshWorkspace();showToast('Shared workspace refreshed.');}catch(error){showToast(error.message);}}

function csvEscape(v){const raw=String(v??'');const s=typeof v==='string'&&/^[=+@\t\r-]/.test(raw)?"'"+raw:raw;return /[",\n]/.test(s)?`"${s.replaceAll('"','""')}"`:s;}
function exportReport(kind, customRows){let rows,headers,file;
  const inv=customRows||allInvoices();
  if(kind==='Customer Outstanding'){rows=customRows&&customRows[0]?.id?customerRows().filter(x=>customRows.some(i=>i.customer===x.customer)):customerRows();headers=['Customer','Code','Invoices','Invoice Amount','Returns','Payment','TDS','Other Deductions','Credit Days','Overdue','Due','Pending Amount'];rows=rows.map(x=>[x.customer,x.code,x.count,x.invoice,x.returns,x.payment,x.tds,x.ppv+x.pqv+x.ccogs+x.taxd,customerCreditDays(x.customer),x.overdue,x.due,x.pending]);file='customer-outstanding';}
  else if(kind==='Bank Reconciliation'){headers=['Date','Bank Reference','Customer','Advice Reference','Credit Amount','Status'];rows=state.bank.map(x=>[x.date,x.ref,x.customer,x.advice,x.amount,x.status]);file='bank-reconciliation';}
  else if(kind==='Debit Note Register'){headers=['Debit Note','Date','Customer','Invoice','Debit Note Type','Amount','Mapping Status'];rows=state.debitNotes.map(x=>[x.id,x.date,x.customer,x.invoice,x.type||'Unknown',x.amount,x.status]);file='debit-note-register';}
  else if(kind==='Unallocated Transactions'){headers=['Source','Date','Reference','Customer','Type','Amount','Issue'];rows=[...state.advice.filter(x=>!x.invoice).map(x=>['Payment Advice',x.date,x.id,x.customer,x.type,x.amount,'Missing invoice']),...state.bank.filter(x=>x.status==='unmatched').map(x=>['Bank Statement',x.date,x.ref,'','Bank credit',x.amount,'No matching advice'])];file='unallocated-transactions';}
  else if(kind==='Payment Advice'){headers=['Advice Number','Date','Customer','Invoice','Transaction Type','Transaction Description','Amount','Bank Reference / UTR'];rows=state.advice.map(x=>[x.id,x.date,x.customer,x.invoice,x.type,x.description||'',x.amount,x.utr]);file='payment-advice';}
  else if(kind==='Returns'){headers=['Document','Type','Date','Customer','Invoice','Quantity','Amount'];rows=[...state.returns.map(x=>[x.id,'Qty Return',x.date,x.customer,x.invoice,x.qty,x.amount]),...state.priceReturns.map(x=>[x.id,'Price Return',x.date,x.customer,x.invoice,'',x.amount])];file='returns';}
  else if(kind==='Settled Invoices'){headers=['Invoice','Customer','Invoice Date','Invoice Amount','Pending Amount','Status'];rows=allInvoices().filter(x=>x.status==='settled').map(x=>[x.id,x.customer,x.date,x.amount,x.pending,'Fully settled']);file='settled-invoices';}
  else if(kind==='Ageing'){headers=['Invoice','Customer','Invoice Date','Age Days','Invoice Amount','Pending Amount','Age Bucket'];rows=allInvoices().map(x=>[x.id,x.customer,x.date,x.age,x.amount,x.pending,x.age>90?'Over 90':x.age>60?'61-90':x.age>30?'31-60':'0-30']);file='ageing-report';}
  else {headers=['Invoice','Customer','Customer Code','Invoice Date','Credit Days','Due Date','Invoice Amount','Qty Return','Price Return','Payment','TDS','PPV','PQV','CCOGS','TaxD','Round Off','Pending Amount','Status'];rows=inv.map(x=>[x.id,x.customer,x.code,x.date,x.creditDays,x.dueDate,x.amount,x.qtyReturn,x.priceReturn,x.Payment,x.TDS,x.PPV,x.PQV,x.CCOGS,x.TaxD,x.roundOff,x.pending,x.status]);file='invoice-outstanding';}
  const csv=[headers,...rows].map(r=>r.map(csvEscape).join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`${file}-${today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showToast(`${kind} report exported.`);
}
