function openBankReceipt(){
  modal('Add bank receipt','Record a cleared bank credit before allocating payment advice.',`<div class="mapping-grid"><label>Bank reference / UTR<input id="bankRef" required /></label><label>Receipt date<input id="bankDate" type="date" value="${today}" /></label><label>Customer (optional)<input id="bankCustomer" /></label><label>Credit amount<input id="bankAmount" type="number" min="0.01" step="0.01" /></label></div>`,`<button class="btn" data-close-modal>Cancel</button><button class="btn primary" id="saveBank">Save receipt</button>`);
  document.getElementById('saveBank').onclick=async()=>{try{
    const ref=document.getElementById('bankRef').value.trim(),date=document.getElementById('bankDate').value,amount=Number(document.getElementById('bankAmount').value);
    if(!ref||!date||!Number.isFinite(amount)||amount<=0)throw new Error('Reference, date and positive amount are required.');
    if(state.bank.some(row=>row.ref===ref))throw new Error('That bank reference already exists. Review the existing receipt first.');
    state.bank.unshift({ref,date,amount,customer:document.getElementById('bankCustomer').value.trim(),status:'unmatched',advice:''});
    await persist();closeModal();render();showToast('Bank receipt saved. It can now be selected in payment advice.');
  }catch(error){showToast(error.message);}};
}
